function parseMaybeJson(value, fallback) {
  if (fallback === undefined) fallback = {};
  if (value && typeof value === "object") return value;
  if (typeof value !== "string") return fallback;
  try { return JSON.parse(value); } catch(e) { return fallback; }
}
const payload = parseMaybeJson($json.payload, $json);
const ctx = payload.execution_context || {};
const state = (payload.context_packet && payload.context_packet.state) || {};
function firstVal() {
  for (var i = 0; i < arguments.length; i++) {
    var v = arguments[i];
    if (v !== undefined && v !== null && String(v).trim() !== "") return v;
  }
  return null;
}
const lead_id = firstVal(ctx.lead_id, payload.lead_id);
const phone = firstVal(ctx.phone, payload.phone);
const email = firstVal(ctx.email, payload.email, "pagos@ahumadadetailing.cl");
const service = firstVal(ctx.service_interest, state.service_interest, "Servicio de lavado");
const amount = firstVal(ctx.quoted_price, state.quoted_price, ctx.amount, 0);
const booking_date = firstVal(ctx.booking_date, state.booking_date);
const booking_time = firstVal(ctx.booking_time, state.booking_time);
const commerceOrder = "AHD-" + lead_id + "-" + Date.now();
return [{
  ...payload,
  payment_context: {
    lead_id, phone, email, service,
    amount: Math.round(Number(amount) || 0),
    commerce_order: commerceOrder,
    subject: "Ahumada Detailing - " + service,
    booking_date, booking_time
  }
}];

const crypto = require("crypto");
const data = $json;
const pCtx = data.payment_context;
const flowApiKey = process.env.FLOW_API_KEY || "";
const flowSecretKey = process.env.FLOW_SECRET_KEY || "";
const flowApiUrl = process.env.FLOW_API_URL || "https://www.flow.cl/api";
const baseUrl = "https://n8n.aahumada.com";
const params = {
  apiKey: flowApiKey,
  amount: String(pCtx.amount),
  commerceOrder: pCtx.commerce_order,
  currency: "CLP",
  email: pCtx.email,
  subject: pCtx.subject,
  urlConfirmation: baseUrl + "/webhook/flow-payment-confirmed",
  urlReturn: baseUrl + "/webhook/flow-payment-return"
};
const sortedKeys = Object.keys(params).sort();
const sigString = sortedKeys.map(function(k) { return k + params[k]; }).join("");
const signature = crypto.createHmac("sha256", flowSecretKey).update(sigString).digest("hex");
return [{
  ...data,
  flow_params: Object.assign({}, params, { s: signature }),
  flow_api_url: flowApiUrl + "/payment/create"
}];

const data = $json;
const pCtx = data.payment_context || {};
const flowUrl = data.url || "";
const flowToken = data.token || "";
const flowOrderId = String(data.flowOrder || "");
const paymentUrl = flowUrl + "?token=" + flowToken;
const amount = pCtx.amount || 0;
const service = pCtx.service || "servicio";
const dateText = (pCtx.booking_date && pCtx.booking_time)
  ? "\nFecha reservada: " + pCtx.booking_date + " a las " + pCtx.booking_time
  : "";
const msg = "Perfecto! Aqui tienes el link para pagar:\n\n" + paymentUrl +
  "\n\nMonto: $" + Number(amount).toLocaleString("es-CL") + " CLP" +
  "\nServicio: " + service + dateText +
  "\n\nUna vez que confirmes el pago, tu cita queda asegurada!";
const payloadObj = {
  ...data,
  payment_url: paymentUrl,
  flow_order_id: flowOrderId,
  message_to_send: msg,
  execution_context: Object.assign({}, data.execution_context || {}, {
    action: "payment_link_sent",
    message: msg,
    state_update: {
      payment_preference: "prepago",
      payment_status: "pending",
      flow_order_id: flowOrderId,
      flow_payment_url: paymentUrl,
      last_bot_action: "payment_link_sent"
    }
  }),
  db_operations: ["messages", "lead_state"]
};
return [{ ...payloadObj, payload: JSON.stringify(payloadObj) }];

